/* source: runtime/styles/tokens.css */
/* tokens.css — design tokens: fonts, neutral/vertical/dark theme variables */

/* ============================================================
   Aircove Customer Portal — styles.css
   Design tokens + component styles. Visual source of truth.
   Componentized: each block below maps 1:1 to a component the
   Codex team will implement (see manifest.json / README.md).

   THEMING is fully declarative:
     <html data-theme="hvac|snow|lawn|pool|roofing|pest|health|beauty"
           data-mode="light|dark">
   app.js only flips these two attributes — every color derives
   from the custom properties defined here.
   ============================================================ */
/* ---------- Fonts ---------- */
@font-face { font-family: "ManropeFallback"; src: local("Manrope"); }

/* ---------- Design tokens : NEUTRALS (light default) ---------- */
:root {
  --font: "Manrope", system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, monospace;

  --ink:      #1d1d1f;
  --ink-2:    #56607a;
  --ink-3:    #9aa0ad;
  --surface:  #ffffff;
  --surface-2:#f5f5f7;
  --base:     #eef1f6;

  /* rgb triplets used inside rgba() */
  --glass:    255,255,255;   /* frosted-panel fill  */
  --hair:     0,0,0;         /* hairline / shadow    */

  --glass-border: rgba(255,255,255,.70);
  --glass-blur:   blur(24px) saturate(180%);
  --shadow-card:  0 8px 28px rgba(13,38,76,.10), inset 0 1px 0 rgba(255,255,255,.70);
  --shadow-float: 0 12px 40px rgba(13,38,76,.16), inset 0 1px 0 rgba(255,255,255,.80);

  --radius-pill: 999px;
  --radius-card: 22px;
  --radius-lg:   24px;
  --radius-md:   14px;
  --radius-sm:   11px;

  /* semantic status colors */
  --ok:     #1f8a44;  --ok-bg:     rgba(52,199,89,.16);
  --warn:   #b5670a;  --warn-bg:   rgba(255,159,10,.16);
  --danger: #c0392b;  --danger-bg: rgba(255,59,48,.12);
  --info:   #0e8fc4;  --info-bg:   rgba(14,143,196,.16);

  /* ACCENT : HVAC (default vertical) */
  --accent:    #0a5ae6;
  --accent-2:  #2a7bff;
  --accent-3:  #3a90ff;
  --accent-rgb:10,90,230;
  --bg-1: #cfe0ff;  --bg-2: #d2f4ec;  --bg-3: #e7dcff;

  --app-bg:
    radial-gradient(120% 90%  at 0%   0%,   var(--bg-1) 0%, transparent 50%),
    radial-gradient(110% 90%  at 100% 0%,   var(--bg-2) 0%, transparent 44%),
    radial-gradient(120% 120% at 90%  100%, var(--bg-3) 0%, transparent 50%),
    var(--base);
}

/* ---------- Design tokens : VERTICAL THEMES ---------- */
:root[data-theme="snow"] {
  --accent:#0e8fc4; --accent-2:#27a6dd; --accent-3:#46b6e6; --accent-rgb:14,143,196;
  --bg-1:#cfe9f6; --bg-2:#d4eef4; --bg-3:#dee9f7;
}

:root[data-theme="lawn"] {
  --accent:#2f9e44; --accent-2:#3fb657; --accent-3:#5fce74; --accent-rgb:47,158,68;
  --bg-1:#d8f0d6; --bg-2:#e4f4d8; --bg-3:#ebf3df;
}

:root[data-theme="pool"] {
  --accent:#0d9488; --accent-2:#15b3a4; --accent-3:#34ccbd; --accent-rgb:13,148,136;
  --bg-1:#cfeeea; --bg-2:#d6f1ec; --bg-3:#ddeff2;
}

:root[data-theme="roofing"] {
  --accent:#4f46e5; --accent-2:#6d63f5; --accent-3:#8b82ff; --accent-rgb:79,70,229;
  --bg-1:#dcdaf8; --bg-2:#e6e2fb; --bg-3:#efe6fb;
}

:root[data-theme="pest"] {
  --accent:#7c3aed; --accent-2:#9554f5; --accent-3:#ad74ff; --accent-rgb:124,58,237;
  --bg-1:#e7dcfb; --bg-2:#efe2fb; --bg-3:#f2e1f6;
}

:root[data-theme="health"] {
  --accent:#0b7285; --accent-2:#0f8ba0; --accent-3:#22a5bb; --accent-rgb:11,114,133;
  --bg-1:#cfe8ee; --bg-2:#d9eef0; --bg-3:#e2ecf6;
}

:root[data-theme="beauty"] {
  --accent:#d6336c; --accent-2:#e64980; --accent-3:#f06595; --accent-rgb:214,51,108;
  --bg-1:#fbd9e5; --bg-2:#fde2ec; --bg-3:#f7e3f5;
}

/* ---------- Design tokens : DARK MODE ---------- */
:root[data-mode="dark"] {
  --ink:#eef2f8; --ink-2:#aab6c8; --ink-3:#7f8aa0;
  --surface:#1b2230; --surface-2:#151b29; --base:#0d1320;
  --glass:38,46,64; --hair:255,255,255;
  --glass-border: rgba(255,255,255,.14);
  --shadow-card:  0 8px 28px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.06);
  --shadow-float: 0 12px 40px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.08);
  --app-bg:
    radial-gradient(120% 90%  at 0%   0%,   rgba(var(--accent-rgb),.24) 0%, transparent 48%),
    radial-gradient(110% 90%  at 100% 0%,   rgba(var(--accent-rgb),.14) 0%, transparent 46%),
    radial-gradient(120% 120% at 90%  100%, rgba(var(--accent-rgb),.18) 0%, transparent 52%),
    var(--base);
}

/* source: runtime/styles/base.css */
/* base.css — reset, base type, links, keyframes */

/* ============================================================
   Base
   ============================================================ */
* { box-sizing: border-box; }

html, body { margin: 0; }

body {
  font-family: var(--font);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration: none; }

a:hover { color: var(--accent-2); }

button { font-family: inherit; }

@keyframes sheen  { 0%{transform:translateX(-140%)} 55%,100%{transform:translateX(260%)} }

@keyframes ping   { 0%{transform:scale(1);opacity:.6} 70%,100%{transform:scale(2.6);opacity:0} }

@keyframes fadein { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:none} }

@keyframes pop    { from{opacity:0;transform:scale(.95) translateY(10px)} to{opacity:1;transform:none} }

@keyframes shimmer{ 0%{background-position:-360px 0} 100%{background-position:360px 0} }

@keyframes route-in{ from{opacity:0;transform:translateY(12px)} to{opacity:1;transform:none} }

.route-enter{ animation: route-in .34s cubic-bezier(.2,.7,.2,1) both; }

@keyframes wt-pulse{ 0%{box-shadow:0 0 0 0 rgba(255,159,10,.55)} 70%{box-shadow:0 0 0 14px rgba(255,159,10,0)} 100%{box-shadow:0 0 0 0 rgba(255,159,10,0)} }

@keyframes wt-glow{ 0%,100%{box-shadow:0 0 0 0 rgba(255,159,10,0)} 50%{box-shadow:0 0 0 3px rgba(255,159,10,.20)} }

.wt-pulse{ animation: wt-pulse 2s cubic-bezier(.4,0,.6,1) infinite; }

@keyframes drawer-in { from { transform: translateX(100%); } to { transform: none; } }

/* source: runtime/styles/components.css */
/* components.css — buttons, badges, tabs, cards, panels, states, toast, drawer, dev harness */

/* ============================================================
   ActionButton  — data-module="action-button"
   ============================================================ */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  border: 0; border-radius: var(--radius-pill); cursor: pointer;
  font-weight: 600; font-size: 13px; padding: 9px 16px;
  white-space: nowrap; transition: transform .08s, filter .15s;
}

.btn:active { transform: translateY(1px); }

.btn[disabled] { opacity: .45; cursor: not-allowed; pointer-events: none; }

.btn--primary {
  background: linear-gradient(180deg, var(--accent-2), var(--accent)); color: #fff;
  box-shadow: 0 4px 12px rgba(var(--accent-rgb), .35), inset 0 1px 0 rgba(255,255,255,.4);
}

.btn--primary:hover { filter: brightness(1.05); }

.btn--ghost {
  background: rgba(var(--glass), .7); border: 1px solid var(--glass-border); color: var(--ink);
}

.btn--danger {
  background: rgba(255,59,48,.08); border: 1px solid rgba(255,59,48,.22); color: var(--danger);
}

.btn--info { background: linear-gradient(180deg, var(--accent-3), var(--accent)); color: #fff; }

.btn--onaccent { background: var(--surface); color: var(--accent); }

.btn--onaccent:hover { filter: brightness(.98); }

.btn--glass-hero { background: rgba(255,255,255,.18); border: 1px solid rgba(255,255,255,.35); color: #fff; }

.btn--glass-hero:hover { background: rgba(255,255,255,.26); }

.btn--block { display: flex; width: 100%; }

.btn--lg { padding: 11px 20px; font-weight: 700; }

/* ============================================================
   PageHeader  — data-module="page-header"
   ============================================================ */
.page-header { display: flex; align-items: flex-end; gap: 14px; margin: 8px 4px 18px; }

.page-header__title { font-weight: 800; font-size: 28px; line-height: 1.18; letter-spacing: -.025em; margin: 0; padding-top: 2px; }

.page-header__sub  { font-size: 14.5px; color: var(--ink-2); margin-top: 3px; }

/* ============================================================
   StatusBadge  — data-module="status-badge"
   ============================================================ */
.status-badge {
  display: inline-flex; align-items: center; gap: 6px;
  border-radius: var(--radius-pill); padding: 5px 12px;
  font-weight: 600; font-size: 12px; white-space: nowrap;
}

.status-badge--ok       { background: var(--ok-bg);     color: var(--ok); }

.status-badge--progress { background: rgba(255,159,10,.20); color: var(--warn); }

.status-badge--scheduled{ background: rgba(120,120,128,.18); color: var(--ink-3); }

.status-badge--warn     { background: var(--warn-bg);   color: var(--warn); }

.status-badge--danger   { background: var(--danger-bg); color: var(--danger); }

.status-badge--info     { background: var(--info-bg);   color: var(--info); }

/* ============================================================
   Tabs / SegmentedControl  — data-module="tabs"
   ============================================================ */
.tabs { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }

.tab {
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
  border-radius: var(--radius-pill); padding: 6px 13px;
  font-weight: 530; font-size: 12.5px; color: var(--ink-2);
  cursor: pointer; white-space: nowrap; user-select: none;
}

.tab:hover { color: var(--ink); }

.tab--active { background: #1d1d1f; color: #fff; font-weight: 590; border-color: transparent; }

:root[data-mode="dark"] .tab--active { background: #fff; color: #10151f; }

.select-pill {
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
  border-radius: var(--radius-pill); padding: 6px 10px;
  font-weight: 530; font-size: 12.5px; color: var(--ink-2); cursor: pointer;
}

/* Card shell — data-module="glass-card" */
.card {
  background: rgba(var(--glass), .5);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border); border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
}

.card__head { display: flex; align-items: center; gap: 10px; padding: 12px 12px 10px; flex-wrap: wrap; }

.card__title { font-weight: 700; font-size: 16px; }

.card--pad { padding: 18px; }

/* ============================================================
   States : loading / empty / error  — data-module respectively
   ============================================================ */
.skeleton {
  background: linear-gradient(90deg, rgba(var(--hair),.06) 25%, rgba(var(--hair),.12) 37%, rgba(var(--hair),.06) 63%);
  background-size: 720px 100%; animation: shimmer 1.4s ease-in-out infinite; border-radius: 8px;
}

.state-block {
  display: flex; flex-direction: column; align-items: center; text-align: center;
  gap: 10px; padding: 54px 24px; animation: fadein .3s ease;
}

.state-block__glyph {
  width: 60px; height: 60px; border-radius: 18px; display: grid; place-items: center;
  font-size: 26px; background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
}

.state-block__glyph--error { background: var(--danger-bg); }

.state-block__title { font-weight: 700; font-size: 17px; }

.state-block__desc { font-size: 13.5px; color: var(--ink-2); max-width: 340px; }

/* ============================================================
   Toast  — data-module="toast"
   ============================================================ */
.toast {
  position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%);
  z-index: 300; display: flex; align-items: center; gap: 10px;
  background: #10151f; color: #fff; border-radius: var(--radius-pill);
  padding: 12px 20px; font-weight: 600; font-size: 13.5px;
  box-shadow: 0 12px 34px rgba(0,0,0,.28); animation: pop .28s ease;
}

.toast__dot { width: 8px; height: 8px; border-radius: var(--radius-pill); background: #34c759; }

/* ============================================================
   Drawer / Modal  — data-module="drawer" / "modal"
   ============================================================ */
.scrim { position: fixed; inset: 0; z-index: 250; background: rgba(10,16,28,.42); backdrop-filter: blur(3px); animation: fadein .2s ease; }

.drawer {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 260; width: min(440px, 92vw);
  background: var(--surface); box-shadow: -20px 0 60px rgba(0,0,0,.28);
  padding: 22px; overflow-y: auto; animation: drawer-in .28s cubic-bezier(.2,.8,.2,1);
}

.drawer__head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }

.drawer__title { font-weight: 800; font-size: 20px; letter-spacing: -.02em; }

.drawer__close { width: 34px; height: 34px; border-radius: var(--radius-pill); background: var(--surface-2); border: 0; cursor: pointer; font-size: 16px; }

/* ============================================================
   Dev harness  — data-dev-toolbar  (PREVIEW ONLY — Codex strips this)
   ============================================================ */
.dev-toolbar {
  position: fixed; left: 50%; bottom: 12px; transform: translateX(-50%);
  z-index: 400; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; justify-content: center;
  background: rgba(16,21,31,.9); backdrop-filter: blur(14px); color: #cfd6e4;
  border: 1px solid rgba(255,255,255,.1); border-radius: 14px;
  padding: 8px 10px; font: 500 11.5px var(--font); max-width: 96vw;
}

.dev-toolbar select, .dev-toolbar button {
  background: rgba(255,255,255,.08); color: #eef2f8; border: 1px solid rgba(255,255,255,.12);
  border-radius: 8px; padding: 5px 8px; font: 500 11.5px var(--font); cursor: pointer;
}

.dev-toolbar__group { display: flex; align-items: center; gap: 4px; }

.dev-toolbar__label { color: #79839a; text-transform: uppercase; letter-spacing: .06em; font-size: 9.5px; }

.dev-toolbar button.is-on { background: var(--accent); border-color: transparent; color: #fff; }

/* Viewport simulation frame (preview harness) */
.viewport-host { display: flex; justify-content: center; }

.viewport-frame { width: 100%; transition: max-width .2s ease; }

.viewport-frame[data-vw="390"]  { max-width: 390px; }

.viewport-frame[data-vw="768"]  { max-width: 768px; }

/* Wave 14.1 — wide presets are TRUE-width: an explicit width (not just max-width)
   so a narrower preview pane never clamps the layout; the host scrolls instead. */
.viewport-frame[data-vw="1180"] { width: 1180px; min-width: 1180px; max-width: 1180px; }

.viewport-frame[data-vw="1440"] { width: 1440px; min-width: 1440px; max-width: 1440px; background: var(--base); }

.viewport-host:has(.viewport-frame[data-vw="1180"]), .viewport-host:has(.viewport-frame[data-vw="1440"]) { justify-content: flex-start; overflow-x: auto; }

.viewport-frame:not([data-vw="1440"]):not([data-vw="full"]) {
  margin: 14px auto; box-shadow: 0 20px 60px rgba(13,38,76,.18); border-radius: 20px; overflow: hidden; background: var(--base);
}

/* Panel — frosted section card used across detail */
.panel {
  background: rgba(var(--glass), .55);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border); border-radius: 20px;
  box-shadow: 0 8px 28px rgba(13,38,76,.10); padding: 20px;
}

.panel__title { font-weight: 700; font-size: 15px; }

.chip { background: rgba(var(--glass), .6); border: 1px solid var(--glass-border); border-radius: var(--radius-pill); padding: 6px 12px; font-weight: 590; font-size: 12px; color: var(--ink-2); cursor: pointer; white-space: nowrap; }


/* ============================================================
   Wave 13 — authenticated live-data states
   (account bootstrap gate, conflict / command-failure banners,
   contact form fields, message send lifecycle)
   ============================================================ */
.account-gate { display: grid; place-items: center; min-height: min(72vh, 640px); }

.account-gate__card { width: 100%; max-width: 460px; }

.account-gate__actions { display: flex; flex-direction: column; gap: 10px; margin-top: 18px; }

.account-gate__route {
  display: inline-flex; align-items: center; gap: 2px; margin: 4px 0 6px; white-space: nowrap;
  padding: 7px 13px; border-radius: var(--radius-pill); font-size: 12.5px; color: var(--ink-2);
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
}

.conflict-banner {
  display: flex; flex-wrap: wrap; gap: 12px; align-items: center; padding: 13px 16px; margin: 0 0 16px;
  border-radius: 14px; background: rgba(255, 159, 10, .1); border: 1px solid rgba(255, 159, 10, .38);
  animation: fadein .3s ease;
}

.conflict-banner__icon {
  width: 34px; height: 34px; border-radius: 11px; display: grid; place-items: center; flex: none;
  font-size: 17px; font-weight: 800; color: var(--warn); background: rgba(255, 159, 10, .16);
}

.conflict-banner__body { flex: 1; min-width: 160px; }

.inline-fail {
  display: flex; gap: 11px; align-items: center; padding: 11px 13px;
  border-radius: 12px; background: var(--danger-bg); border: 1px solid rgba(255, 69, 58, .32);
  animation: fadein .3s ease;
}

.inline-fail__icon {
  width: 22px; height: 22px; border-radius: var(--radius-pill); display: grid; place-items: center; flex: none;
  font-size: 12px; font-weight: 800; color: var(--danger); background: rgba(255, 69, 58, .16);
}

/* contact-details form (profile) */
.field-row { display: flex; flex-direction: column; gap: 6px; }

.field-label { font-size: 12px; font-weight: 700; color: var(--ink-2); letter-spacing: .02em; }

.field {
  width: 100%; padding: 11px 13px; border-radius: 12px; font: inherit; font-size: 14px; color: var(--ink);
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border); outline: none;
}

.field:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(var(--accent-rgb), .14); }

.field[data-state="invalid"] { border-color: var(--danger); box-shadow: 0 0 0 3px rgba(255, 69, 58, .1); }

.field-error { font-size: 12px; color: var(--danger); }

.contact-form { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }

.vw-mobile .contact-form { grid-template-columns: 1fr; }

/* chat message lifecycle */
.msg-bubble[data-state="sending"] { opacity: .55; }

.msg-bubble[data-state="failed"] { border: 1px solid rgba(255, 69, 58, .45); }

.msg-status { font-size: 11.5px; color: var(--ink-3); margin-top: 3px; text-align: right; }

.msg-status--failed { color: var(--danger); }

.msg-retry { color: var(--accent); font-weight: 700; cursor: pointer; margin-left: 6px; }

/* pending buttons (command in flight — duplicate submission disabled) */
.btn[data-state="pending"] { opacity: .8; }

.btn[data-state="failed"] { box-shadow: 0 0 0 2px rgba(255, 69, 58, .28); }

/* cart row while its mutation command is pending */
.cart-row[data-state="pending"] { opacity: .6; pointer-events: none; }

.cart-row__note { font-size: 12px; color: var(--danger); }


/* ============================================================
   Wave 14 — Calm Harbor spa primitives: unmapped raw status,
   visit-mode chip, read-only chip, code chip, card footnote
   ============================================================ */
/* honest UNMAPPED status: the raw backend code, visually distinct from every
   customer-status badge — never restyled to look reassuring */
.status-badge--unmapped {
  background: transparent; border: 1px dashed rgba(120,120,128,.55); color: var(--ink-2);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px; letter-spacing: .03em;
}

/* visit mode is explicit text, never color alone */
.visit-mode {
  display: inline-flex; align-items: center; gap: 6px; border-radius: var(--radius-pill);
  padding: 4px 11px; font-size: 12px; font-weight: 620;
  background: rgba(var(--accent-rgb), .08); border: 1px solid rgba(var(--accent-rgb), .22); color: var(--ink);
  white-space: nowrap;
}

.visit-mode__dot { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); flex-shrink: 0; }

.visit-mode--home .visit-mode__dot { background: transparent; border: 2px solid var(--accent); width: 5px; height: 5px; }

.readonly-chip {
  display: inline-flex; align-items: center; border-radius: var(--radius-pill); padding: 4px 10px;
  font-size: 10.5px; font-weight: 680; letter-spacing: .06em; text-transform: uppercase;
  background: rgba(120,120,128,.14); color: var(--ink-3); margin-left: auto; white-space: nowrap;
}

.code-chip {
  display: inline-block; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10.5px; background: rgba(120,120,128,.12); border-radius: 6px;
  padding: 1px 6px; margin-left: 8px; color: var(--ink-3); overflow-wrap: anywhere;
}

.card__footnote { padding: 12px 16px 14px; font-size: 12px; color: var(--ink-3); border-top: 1px solid var(--glass-border); line-height: 1.5; }

/* source: runtime/forms/portal-form.css */
.pf-shell {
  width: 100%;
  max-width: 780px;
  margin: 0 auto;
  padding: clamp(24px, 5vw, 56px) clamp(14px, 4vw, 24px);
  box-sizing: border-box;
}

.pf {
  --pf-gap: 18px;
  display: block;
  width: 100%;
  color: var(--ink);
  font-family: var(--font);
}

.pf__card {
  background: var(--surface);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: clamp(20px, 4vw, 34px);
}

.pf__head { margin-bottom: 20px; }

.pf__title {
  margin: 0;
  font-size: clamp(21px, 3vw, 27px);
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.15;
}

.pf__sub { margin: 6px 0 0; font-size: 14.5px; line-height: 1.5; color: var(--ink-2); }

.pf__body { display: block; }

.pf-steps { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; margin-bottom: 22px; }

.pf-step {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 11.5px; font-weight: 650; color: var(--ink-3);
  border: 1px solid rgba(var(--hair), .12); border-radius: var(--radius-pill);
  padding: 4px 11px 4px 5px;
}

.pf-step span { max-width: 26ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.pf-step i {
  display: inline-flex; align-items: center; justify-content: center;
  width: 18px; height: 18px; border-radius: 50%;
  background: rgba(120, 120, 128, .14);
  font-style: normal; font-size: 10.5px; font-weight: 750;
}

.pf-step--on { color: var(--ink); border-color: rgba(var(--accent-rgb), .45); }
.pf-step--on i { background: var(--accent); color: #fff; }
.pf-step--done { color: var(--ink-2); }
.pf-step--done i { background: rgba(var(--accent-rgb), .18); color: var(--accent); }

.pf-group { display: flex; flex-direction: column; gap: var(--pf-gap); }

.pf-group__title {
  margin: 0 0 2px;
  font-size: 15px; font-weight: 700; line-height: 1.4; color: var(--ink);
}

.pf-field { display: flex; flex-direction: column; gap: 6px; }

.pf-field__label {
  display: flex; align-items: baseline; gap: 4px;
  font-size: 12px; font-weight: 700; letter-spacing: .02em; color: var(--ink-2);
}

.pf-req { color: var(--danger); font-weight: 800; margin-left: 3px; }

.pf-field__hint { margin: 0; font-size: 12px; line-height: 1.5; color: var(--ink-3); }

.pf-field__error { margin: 0; font-size: 12px; line-height: 1.45; color: var(--danger); }
.pf-field__error:empty { display: none; }

.pf-input {
  width: 100%; padding: 11px 13px; border-radius: var(--radius-md);
  font: inherit; font-size: 14px; color: var(--ink);
  background: var(--surface-2); border: 1px solid rgba(var(--hair), .14);
  outline: none; transition: border-color .16s, box-shadow .16s;
}

.pf-input::placeholder { color: var(--ink-3); }

.pf-input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(var(--accent-rgb), .14); }

.pf-input--area { resize: vertical; min-height: 96px; line-height: 1.55; }

.pf-color { display: flex; align-items: center; gap: 12px; }

.pf-color__swatch {
  width: 46px; height: 44px; padding: 4px; flex: none; cursor: pointer;
  border-radius: var(--radius-md); border: 1px solid rgba(var(--hair), .14);
  background: var(--surface-2);
}

.pf-color__swatch::-webkit-color-swatch { border: 0; border-radius: 9px; }
.pf-color__swatch::-moz-color-swatch { border: 0; border-radius: 9px; }

.pf-color__value { font-family: var(--font-mono); font-size: 13px; color: var(--ink-2); text-transform: uppercase; }

.pf-select { appearance: none; cursor: pointer; padding-right: 38px;
  background-image: linear-gradient(45deg, transparent 50%, var(--ink-3) 50%), linear-gradient(135deg, var(--ink-3) 50%, transparent 50%);
  background-position: calc(100% - 19px) calc(50% + 2px), calc(100% - 14px) calc(50% + 2px);
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.pf-field[data-state="invalid"] .pf-input {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(var(--danger-rgb, 255, 69, 58), .1);
}

.pf-slider { display: flex; align-items: center; gap: 14px; }

.pf-range { flex: 1; appearance: none; height: 4px; border-radius: var(--radius-pill); background: rgba(120, 120, 128, .22); outline: none; }

.pf-range::-webkit-slider-thumb {
  appearance: none; width: 20px; height: 20px; border-radius: 50%;
  background: var(--accent); border: 0; cursor: pointer;
  box-shadow: 0 2px 6px rgba(var(--accent-rgb), .4);
}

.pf-range::-moz-range-thumb {
  width: 20px; height: 20px; border-radius: 50%;
  background: var(--accent); border: 0; cursor: pointer;
  box-shadow: 0 2px 6px rgba(var(--accent-rgb), .4);
}

.pf-range:focus-visible { box-shadow: 0 0 0 3px rgba(var(--accent-rgb), .14); }

.pf-slider__val {
  min-width: 62px; text-align: right;
  font-family: var(--font-mono); font-size: 13px; font-weight: 700; color: var(--ink);
}

.pf-choices { display: flex; flex-direction: column; gap: 9px; }

.pf-choice {
  display: flex; align-items: flex-start; gap: 10px;
  font-size: 14px; line-height: 1.45; color: var(--ink); cursor: pointer;
}

.pf-choice__input { position: absolute; opacity: 0; width: 0; height: 0; }

.pf-choice__label { flex: 1; }

.pf-radio {
  width: 22px; height: 22px; border-radius: var(--radius-pill); flex-shrink: 0; margin-top: 1px;
  border: 2px solid rgba(var(--hair), .28); background: var(--surface-2); display: grid; place-items: center;
  transition: border-color .16s, background .16s;
}

.pf-choice__input[type="radio"]:checked + .pf-radio { border: 0; background: var(--accent); box-shadow: 0 2px 6px rgba(var(--accent-rgb), .4); }
.pf-choice__input[type="radio"]:checked + .pf-radio::after { content: ""; width: 8px; height: 8px; border-radius: var(--radius-pill); background: #fff; }

.pf-check {
  width: 20px; height: 20px; border-radius: 7px; flex-shrink: 0; margin-top: 2px;
  border: 1.5px solid rgba(var(--hair), .28); background: var(--surface-2); color: #fff;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 800; transition: border-color .16s, background .16s;
}

.pf-choice__input[type="checkbox"]:checked + .pf-check { background: var(--accent); border-color: var(--accent); }
.pf-choice__input[type="checkbox"]:checked + .pf-check::after { content: "✓"; }

.pf-choice__input:focus-visible + .pf-radio,
.pf-choice__input:focus-visible + .pf-check { box-shadow: 0 0 0 3px rgba(var(--accent-rgb), .18); }

.pf-chips { display: flex; flex-wrap: wrap; gap: 8px; }

.pf-chip {
  font: inherit; font-size: 13px; font-weight: 600; color: var(--ink-2);
  background: var(--surface-2); border: 1px solid rgba(var(--hair), .14);
  border-radius: var(--radius-pill); padding: 8px 14px; cursor: pointer;
  transition: border-color .16s, background .16s, color .16s;
}

.pf-chip:hover { color: var(--ink); }
.pf-chip--on { background: var(--accent); border-color: var(--accent); color: #fff; }
.pf-chip:focus-visible { outline: none; box-shadow: 0 0 0 3px rgba(var(--accent-rgb), .18); }

.pf-combo { display: block; }

.pf-actions { display: flex; align-items: center; gap: 10px; margin-top: 26px; }
.pf-actions .btn { flex: 0 0 auto; }
.pf-actions .btn--primary { margin-left: auto; }

.pf-note { margin: 16px 0 0; font-size: 12px; line-height: 1.5; color: var(--ink-3); }

.pf-notice {
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  text-align: center; padding: 26px 20px;
  border: 1px solid rgba(var(--hair), .10); border-radius: var(--radius-lg);
  background: var(--surface-2);
}

.pf-notice__glyph {
  width: 40px; height: 40px; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 18px; font-weight: 800;
  background: rgba(120, 120, 128, .14); color: var(--ink-2);
}

.pf-notice--success .pf-notice__glyph { background: var(--ok-bg); color: var(--ok); }
.pf-notice--error .pf-notice__glyph { background: var(--danger-bg); color: var(--danger); }
.pf-notice--blocked .pf-notice__glyph { background: var(--warn-bg); color: var(--warn); }

.pf-notice__title { font-size: 16px; font-weight: 750; }
.pf-notice__body { font-size: 13.5px; line-height: 1.55; color: var(--ink-2); max-width: 42ch; }
.pf-notice .btn { margin-top: 6px; }

.pf__body .pf-notice { margin-top: 4px; }

.pf-skeleton { display: flex; flex-direction: column; gap: 20px; }
.pf-skeleton__row { display: flex; flex-direction: column; gap: 8px; }

.pf-skeleton__bar {
  display: block; height: 42px; border-radius: var(--radius-md);
  background: linear-gradient(90deg, rgba(120, 120, 128, .10), rgba(120, 120, 128, .18), rgba(120, 120, 128, .10));
  background-size: 200% 100%;
  animation: pf-shimmer 1.4s ease-in-out infinite;
}

.pf-skeleton__bar--label { height: 11px; width: 34%; }

@keyframes pf-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .pf-skeleton__bar { animation: none; }
  .pf-input, .pf-chip, .pf-radio, .pf-check { transition: none; }
}

@media (max-width: 640px) {
  .pf__card { padding: 18px 16px 22px; }
  .pf-actions { flex-direction: column-reverse; align-items: stretch; }
  .pf-actions .btn { width: 100%; }
  .pf-actions .btn--primary { margin-left: 0; }
  .pf-step span { display: none; }
  .pf-step { padding: 4px; }
}

/* source: portal form document scope */
html, body { min-height: 100%; }
body { margin: 0; background: var(--app-bg); color: var(--ink); font-family: var(--font); }

